(2724635, 379117, 61863, '<td valign="top">I like this, good use of humour and it works for me - perhaps a tiny bit more light on Homer''s face (JMO)</td>', 'I like this, good use of humour and it works for me - perhaps a tiny bit more light on Homer''s face (JMO)', '2006-08-14 05:48:24.000000', NULL, 1),
