(2724648, 380021, 49109, '<td valign="top">nice idea, but too much post-processing, face looks painted, hair looks overshapened</td>', 'nice idea, but too much post-processing, face looks painted, hair looks overshapened', '2006-08-14 06:01:30.000000', NULL, 1),
