(2724675, 378851, 52130, '<td valign="top">love the bending and the blue smoke, lovely.</td>', 'love the bending and the blue smoke, lovely.', '2006-08-14 06:34:19.000000', NULL, 1),
(2724678, 379479, 52130, '<td valign="top">mmm, spicy! I think if the flames had been closer and  the table''s horizon straighted, it might have been better. 8</td>', 'mmm, spicy! I think if the flames had been closer and  the table''s horizon straighted, it might have been better. 8', '2006-08-14 06:35:27.000000', NULL, 1),
