(2724687, 379916, 52130, '<td valign="top">I love all of the shades of color in this.</td>', 'I love all of the shades of color in this.', '2006-08-14 06:38:15.000000', NULL, 1),
(2724688, 379417, 52130, '<td valign="top">I like the simple beauty in this, but it''s a shame the flame couldn''t be centered and have a more symmetrical glow to it.</td>', 'I like the simple beauty in this, but it''s a shame the flame couldn''t be centered and have a more symmetrical glow to it.', '2006-08-14 06:39:07.000000', NULL, 1),
