INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2730540, 379713, 41554, '<td valign="top">Nice sky, I wish there was a little bit more of land to balance the pic.</td>', 'Nice sky, I wish there was a little bit more of land to balance the pic.', '2006-08-15 19:00:12.000000', NULL, 1),
(2730542, 379916, 63882, '<td valign="top">Excellent image. Orange and blue always work so well together. I like your chosen crop. Should do well in the challenge.</td>', 'Excellent image. Orange and blue always work so well together. I like your chosen crop. Should do well in the challenge.', '2006-08-15 19:00:17.000000', NULL, 1),
(2730557, 379297, 41554, '<td valign="top">Forest fires... probably the ugliest of all fires (also can be spectacularly ugly). The pic is more focused on the smoke and is rather dark overall.</td>', 'Forest fires... probably the ugliest of all fires (also can be spectacularly ugly). The pic is more focused on the smoke and is rather dark overall.', '2006-08-15 19:02:43.000000', NULL, 1),
