(2737035, 379854, 62009, '<td valign="top">very noisy, but it''s nice to see someone who knows what the cedar wrap is for when you decided to smoke the cigar</td>', 'very noisy, but it''s nice to see someone who knows what the cedar wrap is for when you decided to smoke the cigar', '2006-08-17 15:20:10.000000', NULL, 1),
(2737040, 378888, 62009, '<td valign="top">But a single flame burns to remind us of those who have passed</td>', 'But a single flame burns to remind us of those who have passed', '2006-08-17 15:21:43.000000', NULL, 1),
(2737041, 380053, 62009, '<td valign="top">I know where there''s smoke, there''s fire, but I''d like to see some of it in this challenge</td>', 'I know where there''s smoke, there''s fire, but I''d like to see some of it in this challenge', '2006-08-17 15:22:03.000000', NULL, 1),
