(2741539, 379976, 48389, '<td valign="top">Great idea, good detail and colour in the flame but for me the B/G is a little distracting (MHO)</td>', 'Great idea, good detail and colour in the flame but for me the B/G is a little distracting (MHO)', '2006-08-19 11:51:43.000000', NULL, 1),
(2741543, 377165, 48389, '<td valign="top">Nice composition, detail is good and I like the colour and movement you have captured in the flame :o)</td>', 'Nice composition, detail is good and I like the colour and movement you have captured in the flame :o)', '2006-08-19 11:52:59.000000', NULL, 1),
(2741546, 379843, 48389, '<td valign="top">I like the idea and the misty B/G helps give an eery feel to this shot. The flame on the ''ball'' are good and you have captured some nice colour :o)</td>', 'I like the idea and the misty B/G helps give an eery feel to this shot. The flame on the ''ball'' are good and you have captured some nice colour :o)', '2006-08-19 11:54:05.000000', NULL, 1),
(2741548, 378888, 48389, '<td valign="top">Is it just me or is this like looking at someones body? Good colour :o)</td>', 'Is it just me or is this like looking at someones body? Good colour :o)', '2006-08-19 11:54:38.000000', NULL, 1),
(2741549, 379933, 48389, '<td valign="top">Nicely titled, I like the colour of the flame and the shapes it has created! :o)</td>', 'Nicely titled, I like the colour of the flame and the shapes it has created! :o)', '2006-08-19 11:55:09.000000', NULL, 1);
